#!/usr/bin/env bash
set -Eeuo pipefail

# HYPER-HOST CS 1.6 Runtime Manager v6
# Adds a separate Runtime tab and transactional engine/mod updater.

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] Run as root/sudo" >&2; exit 1; }

ROOT="${1:-/root/hyper-hosting-panel}"
AUTO_SID="${2:-0}"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-runtime-manager-v6-backup-${STAMP}"

BOOT="$ROOT/cs16-panel/app/bootstrap.php"
INDEX="$ROOT/cs16-panel/public/index.php"
INSTALL="$ROOT/install-cs16-panel.sh"
BIN_DIR="$ROOT/cs16-panel/bin"
PANE_SRC="$ROOT/cs16-panel/app/runtime-pane.php"
RUNTIME_CTL_SRC="$BIN_DIR/hyper-cs16-runtime-ctl"

for f in "$BOOT" "$INDEX" "$INSTALL"; do
  [[ -f "$f" ]] || { echo "[ERROR] Missing $f" >&2; exit 2; }
done

mkdir -p "$BACKUP" "$BIN_DIR"
cp -a "$BOOT" "$BACKUP/bootstrap.php"
cp -a "$INDEX" "$BACKUP/index.php"
cp -a "$INSTALL" "$BACKUP/install-cs16-panel.sh"
[[ -f "$PANE_SRC" ]] && cp -a "$PANE_SRC" "$BACKUP/runtime-pane.php" || true
[[ -f "$RUNTIME_CTL_SRC" ]] && cp -a "$RUNTIME_CTL_SRC" "$BACKUP/hyper-cs16-runtime-ctl" || true

echo "=============================================================="
echo " HYPER-HOST CS 1.6 RUNTIME MANAGER v6"
echo " Repo:   $ROOT"
echo " Server: #$AUTO_SID"
echo " Backup: $BACKUP"
echo "=============================================================="

echo "[1/8] Installing Runtime Manager sources into repository..."
base64 -d > "$RUNTIME_CTL_SRC" <<'RUNTIME_B64'

RUNTIME_B64
chmod 0755 "$RUNTIME_CTL_SRC"

base64 -d > "$PANE_SRC" <<'PANE_B64'

PANE_B64
chmod 0644 "$PANE_SRC"

python3 -m py_compile "$RUNTIME_CTL_SRC"
php -l "$PANE_SRC" >/dev/null

echo "[2/8] Patching bootstrap.php..."
python3 - "$BOOT" <<'PY'
from pathlib import Path
import sys

p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8')

s=s.replace("const HYPER_CS16_PANEL_BUILD = '3.5-exact-archive';", "const HYPER_CS16_PANEL_BUILD = '6.0-runtime-manager';")

if 'function runtime_ctl(' not in s:
    anchor="function ctl_error(array $r,string $fallback='Операция не выполнена'): string {"
    pos=s.find(anchor)
    if pos < 0:
        raise SystemExit('[PATCH ERROR] bootstrap ctl_error anchor not found')
    helper=r'''function runtime_ctl(array $args,int $timeout=3600): array {
    $cmd=['sudo','-n','/usr/local/sbin/hyper-cs16-runtime-ctl']; foreach($args as $a)$cmd[]=(string)$a;
    $escaped=implode(' ',array_map('escapeshellarg',$cmd));
    $des=[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']];
    $p=proc_open($escaped,$des,$pipes,null,['PATH'=>'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin']);
    if(!is_resource($p)) return ['ok'=>false,'error'=>'Cannot start runtime control process'];
    fclose($pipes[0]); stream_set_blocking($pipes[1],false); stream_set_blocking($pipes[2],false);
    $out='';$err='';$start=microtime(true);
    while(true){$st=proc_get_status($p);$out.=stream_get_contents($pipes[1]);$err.=stream_get_contents($pipes[2]);if(!$st['running'])break;if(microtime(true)-$start>$timeout){proc_terminate($p,15);usleep(300000);proc_terminate($p,9);$err.="\nTimeout";break;}usleep(50000);}
    $out.=stream_get_contents($pipes[1]);$err.=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($p);
    $text=trim($out);$data=json_decode($text,true);
    if(is_array($data)){if($code!==0&&!isset($data['ok']))$data['ok']=false;if(trim($err)!==''&&!isset($data['stderr']))$data['stderr']=trim($err);$data['code']=$code;return $data;}
    return ['ok'=>$code===0,'output'=>$text,'stderr'=>trim($err),'error'=>trim($err)?:($code===0?'':'Runtime command failed'),'code'=>$code];
}

'''
    s=s[:pos]+helper+s[pos:]

p.write_text(s,encoding='utf-8')
PY
php -l "$BOOT" >/dev/null

echo "[3/8] Patching panel Runtime tab/actions..."
python3 - "$INDEX" <<'PY'
from pathlib import Path
import sys

p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8')

if "if($action==='runtime_update')" not in s:
    anchor="        if($action==='save_server_settings'){"
    pos=s.find(anchor)
    if pos < 0:
        raise SystemExit('[PATCH ERROR] POST action anchor not found')
    actions=r'''        if($action==='runtime_update'){
            $id=(int)($_POST['id']??0);require_perm('server.maintenance',$id);server_row($id);
            $component=(string)($_POST['component']??'recommended');
            $allowed=['recommended','all','hlds','rehlds','regamedll','metamod','reapi','amxx19','amxx110','reunion','yapb'];
            if(!in_array($component,$allowed,true))throw new RuntimeException('Неизвестный компонент Runtime');
            $r=runtime_ctl(['update',$id,$component],3600);
            if(empty($r['ok'])){
                $extra=!empty($r['rolled_back'])?' Изменения автоматически откатились на полный backup.':' Автоматический rollback не подтверждён — проверь вывод операции.';
                throw new RuntimeException(ctl_error($r,'Обновление Runtime не выполнено').$extra);
            }
            $acts=is_array($r['actions']??null)?$r['actions']:[];
            audit('runtime_update',$component.' · '.implode('; ',$acts),$id);
            flash('Runtime обновлён и сервер проверен. Игровая сборка сохранена. Backup: '.(string)($r['backup']??'').($acts?' · '.implode('; ',array_slice($acts,0,8)):'') );
            redirect('/?page=server&id='.$id.'#runtime');
        }
        if($action==='runtime_rollback'){
            $id=(int)($_POST['id']??0);require_perm('server.maintenance',$id);server_row($id);
            $backup=trim((string)($_POST['backup']??''));
            if($backup==='')throw new RuntimeException('Выбери Runtime backup');
            $r=runtime_ctl(['rollback',$id,$backup],2400);
            if(empty($r['ok']))throw new RuntimeException(ctl_error($r,'Rollback Runtime не выполнен'));
            audit('runtime_rollback',$backup,$id);
            flash('Runtime и вся сборка восстановлены из backup '.$backup);
            redirect('/?page=server&id='.$id.'#runtime');
        }

'''
    s=s[:pos]+actions+s[pos:]

# Load Runtime status before FastDL state.
status_call="$runtime=runtime_ctl(['status',$id],20);if(empty($runtime['ok']))$runtime=['targets'=>[],'installed'=>[],'health'=>[],'backups'=>[],'legacy_4419'=>false,'needs_reapi'=>false,'configured_plugins'=>0];"
if status_call not in s:
    anchor="$fastdl=ctl(['fastdl-status',$id],15);"
    pos=s.find(anchor)
    if pos < 0:
        raise SystemExit('[PATCH ERROR] fastdl status anchor not found')
    s=s[:pos]+status_call+s[pos:]

if 'data-bs-target="#runtime"' not in s:
    anchor='<li><button data-bs-toggle="pill" data-bs-target="#mods">Моды</button></li><?php endif;?>'
    if anchor not in s:
        raise SystemExit('[PATCH ERROR] Mods tab anchor not found')
    s=s.replace(anchor,anchor+'<?php if(can_perm(\'server.maintenance\',$id)):?><li><button data-bs-toggle="pill" data-bs-target="#runtime"><i class="fa-solid fa-microchip me-1"></i>Runtime</button></li><?php endif;?>',1)

include="<?php if(can_perm('server.maintenance',$id)){ require dirname(__DIR__).'/app/runtime-pane.php'; } ?>"
if include not in s:
    anchor='<div class="tab-pane fade" id="ftp">'
    pos=s.find(anchor)
    if pos < 0:
        raise SystemExit('[PATCH ERROR] FTP pane anchor not found')
    s=s[:pos]+include+s[pos:]

p.write_text(s,encoding='utf-8')
PY
php -l "$INDEX" >/dev/null

echo "[4/8] Making Runtime Manager persistent in install-cs16-panel.sh..."
python3 - "$INSTALL" <<'PY'
from pathlib import Path
import sys

p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8')

line='install -m 0755 "$SRC_DIR/bin/hyper-cs16-runtime-ctl" /usr/local/sbin/hyper-cs16-runtime-ctl'
if line not in s:
    anchor='install -m 0755 "$SRC_DIR/bin/hyper-cs16-ctl" /usr/local/sbin/hyper-cs16-ctl'
    if anchor not in s:
        raise SystemExit('[PATCH ERROR] installer ctl anchor not found')
    s=s.replace(anchor,anchor+'\n'+line,1)

sudo='www-data ALL=(root) NOPASSWD: /usr/local/sbin/hyper-cs16-runtime-ctl *'
if sudo not in s:
    anchor='www-data ALL=(root) NOPASSWD: /usr/local/sbin/hyper-cs16-ctl *'
    if anchor not in s:
        raise SystemExit('[PATCH ERROR] installer sudoers anchor not found')
    s=s.replace(anchor,anchor+'\n'+sudo,1)

p.write_text(s,encoding='utf-8')
PY
bash -n "$INSTALL"

echo "[5/8] Installing Runtime Manager on this node..."
install -m 0755 "$RUNTIME_CTL_SRC" /usr/local/sbin/hyper-cs16-runtime-ctl
python3 -m py_compile /usr/local/sbin/hyper-cs16-runtime-ctl

if ! grep -qF '/usr/local/sbin/hyper-cs16-runtime-ctl *' /etc/sudoers.d/hyper-cs16-panel 2>/dev/null; then
  echo 'www-data ALL=(root) NOPASSWD: /usr/local/sbin/hyper-cs16-runtime-ctl *' >> /etc/sudoers.d/hyper-cs16-panel
fi
chmod 0440 /etc/sudoers.d/hyper-cs16-panel
visudo -cf /etc/sudoers.d/hyper-cs16-panel >/dev/null

mkdir -p /var/lib/hyper-cs16/runtime-stack /srv/hyper-cs16/runtime-backups /srv/hyper-cs16/runtime-cache
chown root:cs16 /var/lib/hyper-cs16/runtime-stack
chmod 0750 /var/lib/hyper-cs16/runtime-stack
chown -R root:cs16 /srv/hyper-cs16/runtime-backups 2>/dev/null || true
chmod 0750 /srv/hyper-cs16/runtime-backups 2>/dev/null || true

echo "[6/8] Publishing patched UI to live panel..."
DOMAIN="$(python3 - <<'PY'
import json
try:
    d=json.load(open('/etc/hyper-cs16/runtime.json',encoding='utf-8'))
    print(d.get('domain') or 'www.avito.hyper-host.pw')
except Exception:
    print('www.avito.hyper-host.pw')
PY
)"
SITE_BASE="/var/www/hyper-host-sites/${DOMAIN}"
SITE_PUBLIC="$SITE_BASE/public_html"
[[ -d "$SITE_BASE/app" && -d "$SITE_PUBLIC" ]] || { echo "[ERROR] Live panel directory not found: $SITE_BASE" >&2; exit 3; }

cp -a "$SITE_BASE/app/bootstrap.php" "$BACKUP/bootstrap.php.live" 2>/dev/null || true
cp -a "$SITE_PUBLIC/index.php" "$BACKUP/index.php.live" 2>/dev/null || true
install -m 0644 "$BOOT" "$SITE_BASE/app/bootstrap.php"
install -m 0644 "$PANE_SRC" "$SITE_BASE/app/runtime-pane.php"
install -m 0644 "$INDEX" "$SITE_PUBLIC/index.php"
chown www-data:www-data "$SITE_BASE/app/bootstrap.php" "$SITE_BASE/app/runtime-pane.php" "$SITE_PUBLIC/index.php"
php -l "$SITE_BASE/app/bootstrap.php" >/dev/null
php -l "$SITE_BASE/app/runtime-pane.php" >/dev/null
php -l "$SITE_PUBLIC/index.php" >/dev/null

while read -r svc; do
  [[ -n "$svc" ]] || continue
  systemctl reload "$svc" 2>/dev/null || true
done < <(systemctl list-units --type=service --state=running --no-legend 2>/dev/null | awk '/php.*fpm/ {print $1}')

echo "[7/8] Runtime Manager self-check..."
/usr/local/sbin/hyper-cs16-runtime-ctl --help >/dev/null
if [[ "$AUTO_SID" =~ ^[0-9]+$ ]] && [[ "$AUTO_SID" -gt 0 ]]; then
  echo "--- BEFORE SERVER #$AUTO_SID ---"
  /usr/local/sbin/hyper-cs16-runtime-ctl status "$AUTO_SID" || true
fi

echo "[8/8] Safe runtime migration..."
if [[ "$AUTO_SID" =~ ^[0-9]+$ ]] && [[ "$AUTO_SID" -gt 0 ]]; then
  set +e
  RESULT="$(/usr/local/sbin/hyper-cs16-runtime-ctl update "$AUTO_SID" recommended)"
  RC=$?
  set -e
  echo "$RESULT"
  if [[ $RC -ne 0 ]]; then
    echo "[ERROR] Recommended Runtime migration failed. Runtime Manager attempted a full automatic rollback; inspect the JSON above." >&2
    exit $RC
  fi
  echo "--- AFTER SERVER #$AUTO_SID ---"
  /usr/local/sbin/hyper-cs16-runtime-ctl status "$AUTO_SID"
else
  echo "[INFO] AUTO_SID=0: Runtime tab installed, no game server was changed."
fi

echo
echo "=============================================================="
echo "[SUCCESS] HYPER-HOST RUNTIME MANAGER v6 INSTALLED"
echo "Panel tab: Runtime"
echo "Binary:    /usr/local/sbin/hyper-cs16-runtime-ctl"
echo "Backups:   /srv/hyper-cs16/runtime-backups/<server_id>/"
echo
echo "Recommended migration:"
echo "  SteamCMD steam_legacy base -> ReHLDS -> ReGameDLL -> Metamod-R"
echo "  ReAPI is refreshed only when the current build uses/requires it."
echo
echo "Separate controls in Runtime tab:"
echo "  HLDS base / ReHLDS / ReGameDLL / Metamod-R / ReAPI"
echo "  AMXX 1.9 / AMXX 1.10 / ReUnion / YaPB / full rollback"
echo
echo "Preserved:"
echo "  Zombie Plague / custom AMXX plugins / configs / models / sounds"
echo "  sprites / maps / SQL / VIP/Admin / weapons / knives"
echo "Panel backup: $BACKUP"
echo "=============================================================="
